const M = window.Klimatperspektiv, $ = id => document.getElementById(id);
const esc = x => String(x ?? '').replace(/[&<>"']/g, c => ({'&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'}[c]));
const nf = (x, d = 0) => { if (x == null || !Number.isFinite(x)) return '–'; const t = new Intl.NumberFormat('sv-SE', {maximumFractionDigits: d, minimumFractionDigits: d}).format(x); return /^[−-]0([,.]0+)?$/.test(t) ? t.slice(1) : t; };
const sig = x => { if (x == null || !Number.isFinite(x)) return '–'; const a = Math.abs(x); if (a < 5e-4) return '0'; return nf(x, a >= 100 ? 0 : a >= 10 ? 1 : a >= 1 ? 2 : 3); };
const kt = x => nf(x / 1000, Math.abs(x) >= 1e5 ? 0 : 1);
const json = id => JSON.parse($(id).textContent);
const D = {deso: json('d-deso'), land: json('d-land'), grund: json('d-grund'), kol: json('d-kol'), utb: json('d-utb'), meta: json('d-meta')};
const S = M.prepare(D);
const STORE = 'klimatperspektiv-malmo-antaganden';
const store = {get() { try { return JSON.parse(localStorage.getItem(STORE) || 'null'); } catch (e) { return null; } },
  set(v) { try { localStorage.setItem(STORE, JSON.stringify(v)); } catch (e) { /* lagring ej tillgänglig */ } }};
let P = M.params(store.get() || {}), R, Rref, V = null, Vref = null;
function rakna() { R = M.compute(S, P); Rref = M.harCirk(P) ? M.compute(S, M.utanCirk(P)) : R; V = null; }
rakna();
/* Rader per DeSO för valt år, med undvikna utsläpp mot referensen (hela behovet nybyggs). */
function cur() {
  if (V) return V;
  V = M.view(S, R, P.ar); Vref = Rref === R ? V : M.view(S, Rref, P.ar);
  const u = M.undvikt(V, Vref); V.rows.forEach((r, i) => { r.undvikt = u[i]; }); V.city.undvikt = u.reduce((a, b) => a + b, 0);
  V.rows.forEach((r,i)=>{r.cirk_bidrag=-r.undvikt;r.undviket_bygg=Vref.rows[i].bygg_tot-r.bygg_tot;r.undviket_total=Vref.rows[i].total-r.total;});
  return V;
}

/* ---------- perspektiv, färger och nyckeltal ---------- */
const PF = {total: ['#167567', '#e3efe6', '#0d4a41'], mark: ['#5d9b57', '#e8f2df', '#2c5e2b'], ny: ['#c9982b', '#f8efd6', '#7d5a0e'],
  transport: ['#2a78d6', '#e1edfa', '#123f7c'], energi: ['#8a63c9', '#eee6f8', '#4b2b85'], cirk: ['#2f9c8a', '#dff1ec', '#125a4e']};
const KF = {byggdel:'#bc8c6b', mark: '#5d9b57', bygg: '#c9982b', anl: '#e6c777', omb: '#2f9c8a', mob: '#2a78d6', nymob: '#86b4ea', energi: '#8a63c9', nydrift: '#bda8e6'};
const STACK = ['mark', 'ny', 'transport', 'energi', '-anpassning', 'cirk', 'total'];   // ordningen i lagerstapeln
