  transport: [['mob_tot', 'Mobilitet, summa'], ['mob', 'Mobilitet i befintlig stad'], ['nymob', 'Nya invånares mobilitet'], ['bil_hh', 'Bilar per hushåll 2024']],
  energi: [['energi_tot', 'Energi, summa'], ['energi', 'Energi i befintliga byggnader'], ['nydrift', 'Nya byggnaders energi'], ['kwh_m2', 'Energianvändning per m² 2024']],
  cirk: [['undvikt', 'Undviket byggande och mark'], ['byggdel','Separata byggdelars faktiska utsläpp'], ['omb', 'Omvandling, påbyggnad och renovering'], ['bygg_tot', 'Allt byggande: nytt och cirkulärt'], ['pot_omv', 'Omvandlingspotential: lokalyta'], ['pot_pab', 'Påbyggnadspotential: flerbostadshus']]
};
const HUVUD = {total: 'total', mark: 'mark', ny: 'ny_tot', transport: 'mob_tot', energi: 'energi_tot', cirk: 'undvikt'};   // nyckeltal i små kartor och klimatkort
const TEXT = {
