const UNITS = ['t', 't_ha', 'kg_ha', 't_inv'];
const isAck = () => P.ar === 'ack';
const yearLabel = y => y === 'ack' ? '2025–2050' : String(y);
const unitBase = u => isAck() ? ({t: 't CO₂e 2025–2050', t_ha: 't CO₂e per ha, 2025–2050', kg_ha: 'kg CO₂e per ha, 2025–2050', t_inv: 't CO₂e per invånare, 2025–2050'}[u])
  : ({t: 't CO₂e per år', t_ha: 't CO₂e per ha och år', kg_ha: 'kg CO₂e per ha och år', t_inv: 't CO₂e per invånare och år'}[u]);
const statisk = k => k in M.STATISKA;
const unitLabel = (k, u) => statisk(k) ? M.STATISKA[k] : unitBase(u);
const metricLabel = k => { for (const l of Object.values(NYCKELTAL)) for (const [a, b] of l) if (a === k) return b; return k; };
const mobLabel = () => P.perspektiv === 'A' ? 'A · Trafik inom området' : 'B · Hushållens bilar';
const scenLabel = () => M.harCirk(P) ? 'Cirkulära åtgärder valda' : 'Referens: hela behovet nybyggs';
const changed = () => P.elVal !== M.DEFAULTS.elVal || Object.keys(M.DEFAULTS).some(k => !['ar', 'perspektiv', 'efEl'].includes(k) && String(P[k]) !== String(M.params({elVal: P.elVal})[k]));

const st = {view: 'overview', persp: 'total', metric: {...HUVUD}, unit: 't', selected: null, osm: true, dev: true, sort: ['v', -1], filter: ''};
const HEAD = {
  overview: ['KLIMATPERSPEKTIV', 'Fem perspektiv på Malmös klimatpåverkan.<br><em>Samma karta, samma antaganden.</em>', 'Klimatpåverkan per DeSO 2024–2050 när staden växer: mark, nybyggnad, transporter, energi och cirkularitet. Välj perspektiv i lagerstapeln till vänster.'],
  map: ['KARTA & KLIMATKORT', 'Var uppstår klimatpåverkan?', 'Välj perspektiv, nyckeltal och enhet. Klicka på ett område för att se dess klimatkort med alla fem perspektiv.'],
  pop: ['BEFOLKNING & NYBYGGNATION', 'Hur många blir vi, och vad behöver byggas?', 'Ange folkmängden 2030–2050, typ av bebyggelse, klimatpåverkan per m² BTA och var det byggs. Resultatet räknas om direkt.'],
