  sources: ['KÄLLKONTROLL', 'Källornas stöd och begränsningar', 'Identitet, sakstöd och lokal tillämpbarhet kontrolleras separat.'],
  method: ['METOD & KÄLLOR', 'Så räknas resultatet', 'Systemgränser, formler, underlag, begränsningar och referenser.']
};
const post = (l, v) => '<span class="ctx-item"><small>' + l + '</small>' + v + '</span>';
const kontext = extra => '<div class="ctx-bar"><span class="ctx-title">Visas nu</span>' + post('Perspektiv', esc(pNamn(st.persp))) + post('År', esc(yearLabel(P.ar))) + (extra || '') + post('Mobilitet', esc(mobLabel())) + post('Byggande', esc(scenLabel())) + '</div>';
const notice = (html, cls = '') => '<div class="notice ' + cls + '">' + html + '</div>';
const flikar = () => '<div class="kp-flikar" role="group" aria-label="Perspektiv">' + STACK.filter(p => p[0] !== '-').map(p => '<button data-persp="' + p + '" class="' + (st.persp === p ? 'active' : '') + '"><i style="background:' + PF[p][0] + '"></i>' + esc(pNamn(p)) + '</button>').join('') + '</div>';

function renderChrome() {
  $('kp-stack').innerHTML = STACK.map(p => p === '-anpassning'
    ? '<button disabled title="Klimatanpassning ingår inte i modellen: riskbilden uttrycks inte i CO₂e"><i style="background:#c9706b"></i><span>Klimatanpassning<small>ingår inte</small></span></button>'
    : '<button data-persp="' + p + '" class="' + (st.persp === p ? 'active' : '') + '"><i style="background:' + PF[p][0] + '"></i><span>' + esc(pNamn(p)) + '</span></button>').join('');
