function setP(patch) { const next=M.params({...P,...patch}); M.compute(S,next); P=next; rakna(); store.set(P); renderChrome(); render(); }

/* ---------- diagram (SVG) ---------- */
function niceStep(raw) { if (!(raw > 0)) return 1; const p = Math.pow(10, Math.floor(Math.log10(raw))), f = raw / p; return (f <= 1 ? 1 : f <= 2 ? 2 : f <= 2.5 ? 2.5 : f <= 5 ? 5 : 10) * p; }
/* Staplade staplar. kat: [{etikett, staplar: [{namn, v: {nyckel: värde}}], vald, attr}], serier: [[nyckel, namn, färg]]. */
function staplar(kat, serier, o = {}) {
  const W = 640, H = o.h || 250, L = 46, Rm = 8, T = 12, B = 34, div = o.div || 1, dec = o.dec ?? 0;
  const tot = s => serier.reduce((a, [k]) => a + Math.max(0, s.v[k] || 0), 0) / div;
  const max = Math.max(1e-9, ...kat.flatMap(c => c.staplar.map(tot))), step = niceStep(max / 4), top = Math.ceil(max / step) * step;
  const Y = v => T + (H - T - B) * (1 - v / top), bw = (W - L - Rm) / kat.length;
  let h = '<svg viewBox="0 0 ' + W + ' ' + H + '" role="img" aria-label="' + esc(o.aria || 'Stapeldiagram') + '">';
  for (let v = 0; v <= top + 1e-9; v += step) h += '<line class="grid" x1="' + L + '" x2="' + (W - Rm) + '" y1="' + Y(v) + '" y2="' + Y(v) + '"/><text x="' + (L - 6) + '" y="' + (Y(v) + 3.5) + '" text-anchor="end">' + nf(v, step < 1 ? 1 : 0) + '</text>';
  kat.forEach((c, i) => {
    const n = c.staplar.length, w = Math.min(54, bw * 0.78 / n), x0 = L + bw * i + (bw - w * n - 4 * (n - 1)) / 2;
    c.staplar.forEach((s, q) => {
      let acc = 0; const x = x0 + q * (w + 4);
      for (const [k, namn, farg] of serier) { const v = Math.max(0, s.v[k] || 0) / div; if (!(v > 0)) continue;
        h += '<rect' + (c.attr ? ' class="klick" ' + c.attr : '') + ' x="' + x.toFixed(1) + '" y="' + Y(acc + v).toFixed(1) + '" width="' + w.toFixed(1) + '" height="' + Math.max(0.5, Y(acc) - Y(acc + v)).toFixed(1) + '" fill="' + farg + '"' + (s.matt ? ' opacity=".45"' : '') + '><title>' + esc(c.etikett + (s.namn ? ' · ' + s.namn : '') + ' · ' + namn + ': ' + nf(v, dec) + ' ' + (o.enhet || '')) + '</title></rect>'; acc += v; }
      if (o.summa !== false) h += '<text x="' + (x + w / 2).toFixed(1) + '" y="' + (Y(acc) - 4).toFixed(1) + '" text-anchor="middle"' + (c.vald ? ' class="vald"' : '') + '>' + nf(acc, dec) + '</text>';
      if (s.namn && n > 1) h += '<text x="' + (x + w / 2).toFixed(1) + '" y="' + (H - 20) + '" text-anchor="middle" style="font-size:9px">' + esc(s.namn) + '</text>';
    });
    h += '<text class="x' + (c.vald ? ' vald' : '') + '" x="' + (L + bw * (i + .5)).toFixed(1) + '" y="' + (H - 6) + '" text-anchor="middle">' + esc(c.etikett) + '</text>';
  });
  return '<div class="kp-chart">' + h + '</svg></div><div class="chart-legend">' + serier.map(([k, namn, farg]) => '<span><i style="background:' + farg + '"></i>' + esc(namn) + '</span>').join('') + (o.legendExtra || '') + '</div>';
}

/* ---------- kartfärger ---------- */
const hex = c => [1, 3, 5].map(i => parseInt(c.slice(i, i + 2), 16));
function ramp(p, t) { const a = hex(PF[p][1]), b = hex(PF[p][2]); return 'rgb(' + a.map((x, i) => Math.round(x + (b[i] - x) * t)).join(',') + ')'; }
function classes(vals) {
  const v = vals.filter(x => x != null && Number.isFinite(x) && x !== 0).sort((a, b) => a - b); if (!v.length) return [];
  const q = k => v[Math.min(v.length - 1, Math.floor(k * v.length))], br = [v[0], q(.2), q(.4), q(.6), q(.8), v[v.length - 1]];
  return br.filter((b, i) => i === 0 || b > br[i - 1]);
}
function colorFor(x, br, p) { if (x == null || !Number.isFinite(x) || x===0 || !br.length) return '#e3e8e4'; if(x<0)return '#c77869'; let k = 0; while (k < br.length - 2 && x > br[k + 1]) k++; return ramp(p, (k + .5) / Math.max(1, br.length - 1)); }

/* ---------- små kartor ---------- */
const MINI = (() => {
  let x0 = 1e9, x1 = -1e9, y0 = 1e9, y1 = -1e9;
  for (const f of D.land.features) for (const poly of (f.geometry.type === 'Polygon' ? [f.geometry.coordinates] : f.geometry.coordinates)) for (const [x, y] of poly[0]) { x0 = Math.min(x0, x); x1 = Math.max(x1, x); y0 = Math.min(y0, y); y1 = Math.max(y1, y); }
  const kx = Math.cos((y0 + y1) / 2 * Math.PI / 180), W = 300, s = W / ((x1 - x0) * kx), H = Math.round((y1 - y0) * s);
  const path = (g, steg) => (g.type === 'Polygon' ? [g.coordinates] : g.coordinates).map(p => p.map(r => { const n = r.length, k = n > 60 ? steg : 1; let d = '';
    for (let i = 0; i < n; i += k) d += (i ? 'L' : 'M') + ((r[i][0] - x0) * kx * s).toFixed(1) + ' ' + ((y1 - r[i][1]) * s).toFixed(1); return d + 'Z'; }).join('')).join('');
  return {W, H, land: D.land.features.map(f => path(f.geometry, 2)).join(''), deso: D.deso.features.map(f => path(f.geometry, 3))};
})();
function miniKarta(p, rows) {
  const k = HUVUD[p], vals = rows.map(r => M.metric(r, k, st.unit)), br = classes(vals), id = 'kp-klipp-' + p;
  return '<svg viewBox="0 0 ' + MINI.W + ' ' + MINI.H + '" aria-hidden="true"><defs><clipPath id="' + id + '"><path d="' + MINI.land + '" clip-rule="evenodd"/></clipPath></defs><path d="' + MINI.land + '" fill="#e3e8e4"/><g clip-path="url(#' + id + ')">' +
    MINI.deso.map((d, i) => '<path d="' + d + '" fill="' + colorFor(vals[i], br, p) + '" stroke="#fff" stroke-width=".25"/>').join('') + '</g></svg>';
}

/* ---------- 01 Översikt ---------- */
function behovTabell(kort) {
  const pr = M.perioder(R), ref = Rref === R ? null : M.perioder(Rref), m = x => nf(x / 1000, 0);
  const rad = (namn, f, cls, d) => '<tr' + (cls ? ' class="' + cls + '"' : '') + '><td>' + namn + '</td>' + pr.map((p, i) => '<td>' + f(p, ref && ref[i]) + '</td>').join('') + '<td>' + d + '</td></tr>';
  const sum = k => pr.reduce((s, p) => s + p[k], 0), lokInv = P.arbPerInv * P.btaArb + P.skolBtaPerInv;
  let h = '<div class="table-wrap calc-full"><table class="kp-tab"><thead><tr><th>Fram till</th>' + pr.map(p => '<th>' + p.till + '<br><small>' + p.fran + '–' + p.till + '</small></th>').join('') + '<th>Summa<br><small>2025–2050</small></th></tr></thead><tbody>';
  h += rad('Folkmängd vid periodens slut', p => nf(p.pop), '', '–') + rad('Nya invånare', p => nf(p.N), '', nf(sum('N')));
  h += rad('Behov av yta, 1 000 m² BTA', p => m(p.behov), 'sum', m(sum('behov')));
