function report(P,S,R,RR,ar=P.ar){
 const C=M.circularComparison(S,R,RR,ar).city,ack=ar==='ack',u=ack?'2025–2050':'år '+ar;
 const rows=[['Referens: byggande och mark',nf((C.byggRef+C.markRef)/1000)+' kt CO₂e'],['Alternativ: byggande och mark',nf((C.byggVal+C.markVal)/1000)+' kt CO₂e'],['Undviket (referens minus alternativ)',nf(C.undviket/1000)+' kt CO₂e'],['Förändringsbidrag (alternativ minus referens)',nf(C.bidrag/1000)+' kt CO₂e']];
