/* Klimatperspektiv – tillägg till Vägvis och Road2Zero-OP:s stilmallar (vagvis_bas.css, r2z_op.css). */
.sidebar{overflow-y:auto;padding:26px 20px}
.project-tag{margin:20px 0 16px}
.kp-rubrik{font-size:9px;letter-spacing:1.4px;color:#acd0bd;margin:0 0 8px;text-transform:uppercase}
.kp-stack{display:grid;gap:4px;margin:0 0 16px}
.kp-stack button{display:flex;align-items:center;gap:9px;text-align:left;background:transparent;color:#cfe4db;border:1px solid #2f5a51;border-radius:8px;padding:7px 9px;font:inherit;font-size:11.5px;cursor:pointer;line-height:1.2}
.kp-stack button i{flex:0 0 22px;width:22px;height:13px;border-radius:3px;transform:skewX(-24deg);border:1px solid #ffffff55}
.kp-stack button:hover{background:#1b4b44}
.kp-stack button.active{background:#e3eee5;color:#143f38;border-color:#e3eee5;font-weight:650}
.kp-stack button[disabled]{opacity:.42;cursor:default;border-style:dashed}
.kp-stack button[disabled]:hover{background:transparent}
.kp-stack button small{display:block;font-size:9px;opacity:.8;font-weight:400}
.model-switch{margin:0 0 14px;gap:5px}
.model-switch button{padding:7px 9px;gap:9px}
.model-switch b{font-size:17px}
.model-switch span{font-size:11px}
.model-switch small{margin-top:1px;font-size:9px}
nav{gap:3px}
.nav{padding:9px 10px;font-size:11.5px}
.side-bottom small{margin-top:10px}
.page-heading h1 em{font-style:normal}

/* perspektivflikar och kontextrad */
.kp-flikar{display:flex;flex-wrap:wrap;gap:6px;margin:0 0 12px}
.kp-flikar button{display:inline-flex;align-items:center;gap:7px;background:#fff;border:1px solid var(--line);border-radius:999px;padding:7px 13px;font:inherit;font-size:12px;color:var(--ink);cursor:pointer}
.kp-flikar button i{width:10px;height:10px;border-radius:50%;display:inline-block}
.kp-flikar button.active{background:var(--dark);border-color:var(--dark);color:#fff}
.ctx-bar{display:flex;flex-wrap:wrap;gap:8px 26px;align-items:center;background:#fff;border:1px solid var(--line);border-radius:12px;padding:10px 16px;margin:0 0 14px;font-size:12.5px;color:var(--ink)}
.ctx-bar .ctx-title{font-size:10px;letter-spacing:1px;color:var(--muted);text-transform:uppercase}
.ctx-item small{font-size:10px;color:var(--muted)}

/* perspektivrader på översikten */
.kp-rad{display:grid;grid-template-columns:168px 1fr 96px;gap:12px;align-items:center;font-size:12px;padding:9px 8px;border-radius:8px;cursor:pointer;border:1px solid transparent;width:100%;background:none;font-family:inherit;text-align:left;color:var(--text)}
.kp-rad:hover{background:#f2f6f1}
.kp-rad.active{border-color:#b9cfc2;background:#eef4ef}
.kp-rad .lbl{display:flex;align-items:center;gap:8px;color:var(--ink);font-weight:600}
.kp-rad .lbl i{width:11px;height:11px;border-radius:3px;display:inline-block;flex:0 0 11px}
.kp-rad b{text-align:right;font-variant-numeric:tabular-nums}
.kp-rad .track{display:flex;height:12px}
.kp-rad .track span{display:block;height:100%}

/* små kartor: fem perspektiv bredvid varandra */
.kp-mini{display:grid;grid-template-columns:repeat(5,1fr);gap:12px}
.kp-mini button{background:#fff;border:1px solid var(--line);border-radius:12px;padding:10px 10px 8px;cursor:pointer;font:inherit;text-align:left;color:var(--text)}
.kp-mini button:hover{border-color:#9fb9ac}
.kp-mini button.active{border-color:var(--teal);box-shadow:0 0 0 2px #16756722}
.kp-mini h3{font-size:12px;margin:0 0 2px;color:var(--ink);display:flex;gap:6px;align-items:center}
.kp-mini h3 i{width:10px;height:10px;border-radius:3px;display:inline-block}
.kp-mini small{display:block;font-size:10px;color:var(--muted);min-height:26px;line-height:1.3}
.kp-mini svg{width:100%;height:auto;display:block;margin-top:4px}
@media(max-width:1250px){.kp-mini{grid-template-columns:repeat(3,1fr)}}
@media(max-width:720px){.kp-mini{grid-template-columns:repeat(2,1fr)}}

/* reglage */
.kp-reglage{display:grid;grid-template-columns:repeat(2,1fr);gap:16px 28px}
.kp-reg label{display:flex;justify-content:space-between;gap:10px;font-size:12px;font-weight:600;color:var(--ink);margin-bottom:4px}
.kp-reg label output{font-variant-numeric:tabular-nums;color:var(--teal)}
.kp-reg input[type=range]{width:100%;accent-color:var(--teal)}
.kp-reg .src{display:block;font-size:10.5px;color:var(--muted);line-height:1.45;margin-top:2px}
.kp-steg{display:inline-flex;align-items:center;justify-content:center;width:20px;height:20px;border-radius:50%;background:var(--dark);color:#fff;font-size:11px;margin-right:7px;flex:0 0 20px}
@media(max-width:900px){.kp-reglage{grid-template-columns:1fr}}
.kp-val{display:flex;flex-wrap:wrap;gap:7px;margin:0 0 14px}
.kp-val button.on{background:var(--dark);color:#fff;border-color:var(--dark)}
.kp-pop{display:grid;grid-template-columns:repeat(5,1fr);gap:12px;margin:6px 0 4px}
.kp-pop label{font-size:11px;font-weight:600;color:var(--ink);display:block}
.kp-pop input{width:100%;margin-top:5px;font-size:14px;font-variant-numeric:tabular-nums}
.kp-pop small{display:block;font-size:10px;color:var(--muted);margin-top:4px}
@media(max-width:900px){.kp-pop{grid-template-columns:repeat(2,1fr)}}

/* tabeller och diagram */
table.kp-tab{width:100%;border-collapse:collapse;font-size:12px}
table.kp-tab th{font-size:10.5px;text-align:right;color:var(--muted);font-weight:600;padding:7px 8px;border-bottom:1px solid var(--line);vertical-align:bottom;white-space:nowrap}
table.kp-tab th:first-child,table.kp-tab td:first-child{text-align:left}
table.kp-tab td{padding:7px 8px;border-bottom:1px solid #eef1ec;text-align:right;font-variant-numeric:tabular-nums}
table.kp-tab tr.sum td{font-weight:700;border-top:2px solid var(--line);color:var(--ink)}
table.kp-tab tr.del td{color:var(--muted);font-size:11.5px}
table.kp-tab tr.del td:first-child{padding-left:20px}
table.kp-tab tr.klick{cursor:pointer}
table.kp-tab tr.klick:hover td{background:#f2f6f1}
table.kp-tab tr.vald td{background:#e8f1ea}
table.kp-tab th[data-sort]{cursor:pointer}
table.kp-tab th.sorted{color:var(--ink)}
.kp-chart svg{width:100%;height:auto;display:block}
.kp-chart text{font-size:10.5px;fill:var(--muted);font-variant-numeric:tabular-nums}
.kp-chart .x{fill:var(--text)}
.kp-chart .grid{stroke:#e6ece6}
.kp-chart rect.klick{cursor:pointer}
.kp-chart rect.klick:hover{opacity:.85}
.kp-chart .vald{font-weight:700;fill:var(--ink)}

/* klimatkort (områdesprofil) */
.kp-kort h4{font-size:11.5px;margin:14px 0 8px;color:var(--ink)}
.kp-profil{display:grid;grid-template-columns:1fr auto;gap:1px 8px;font-size:11.5px;margin-bottom:8px;color:var(--text)}
.kp-profil b{font-variant-numeric:tabular-nums}
.kp-profil .skala{grid-column:1/-1;position:relative;height:6px;border-radius:3px;background:#e7ede9;margin-top:2px}
.kp-profil .skala i{position:absolute;top:-2px;width:4px;height:10px;border-radius:2px;margin-left:-2px}
.kp-profil small{grid-column:1/-1;font-size:10px;color:var(--muted)}
.kp-signal{font-size:11.5px;line-height:1.45;margin:0 0 7px;padding-left:22px;position:relative}
.kp-signal b{position:absolute;left:0;top:0;width:16px;height:16px;border-radius:4px;background:var(--amber-bg);color:var(--amber);font-size:10px;display:flex;align-items:center;justify-content:center;border:1px solid #ead7b7}
.kp-legend-not{font-size:10.5px;color:var(--muted);margin-top:6px}
.kp-varning{border-left:3px solid var(--amber);padding:6px 0 6px 12px;font-size:12px;margin:10px 0;color:#6a4b28}
.kp-formel{background:#f4f7f2;border:1px solid var(--line);border-radius:8px;padding:10px 13px;font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:11.5px;line-height:1.7;white-space:pre-wrap;color:var(--ink);margin:8px 0 14px}
@media print{.kp-flikar,.kp-val{display:none!important}}
table.kp-tab.kp-text td,table.kp-tab.kp-text th{white-space:normal;text-align:left;vertical-align:top;line-height:1.5}
table.kp-tab.kp-text td:first-child{white-space:nowrap;font-weight:600;color:var(--ink)}

