        cumAtemp[i] += (bF + bS + lok[i] + pabI + ersI) * P.atempNy; cumBta[i] += bF + bS + lok[i] + pabI + omvI;
        comp.bygg[yi][i] = ((bF * t.fF * tra + bS * t.fS + lok[i] * t.fL * tra + ersI * (S.bostAndel * t.fF + (1 - S.bostAndel) * t.fL) * tra) * ab + ersI * P.efRivning) / 1000;
        comp.anl[yi][i] = ((bF + bS + lok[i] + ersI) * P.grundKgBta + utv[i] * 1e4 * P.anlKgMark + dF*(rF*bFbh+(1-rF)*bSm)*P.fortAnlKgBta) * t.iAnl / 1000;
        comp.byggdel[yi][i] = (P.komponentAktiv==='ja'?P.antalByggdelar:0)*(P.byggdelDeso?(S.ids[i]===P.byggdelDeso?1:0):wBest[i])/1000*(P.bevaraByggdel==='nej' ? (y===P.arByteRef?P.efByteByggdel:0) : (y===P.arByteRef?P.efBevaraByggdel:0)+(y===P.arByteAlt?P.efByteByggdel:0));
        comp.omb[yi][i] = (omvI * P.efOmv + pabI * P.pabFaktor * t.fF * tra * ab + renI * P.efRenovering) / 1000;
        const d = P.perspektiv === 'A' ? S.A : S.B;
        const shift = P.byteBil2050/100*ramp(y), altPerVkm = P.belaggningBil*P.alternativGpkm/1e6;
        comp.mob[yi][i] = ((d.fuel[i] * t.fl + d.el[i] * t.kEl + d.fordon[i] * t.ip)*(1-shift) + d.vkm[i]*shift*altPerVkm) * t.tr;
        comp.energi[yi][i] = (S.kwhEl[i] * t.fk.el + S.kwhFv[i] * t.fk.fv) / 1000 * t.eff * Math.max(0,1-(S.btaTot[i]>0?(retired[i]+renovated[i]*P.renEnergiBesparing/100)/S.btaTot[i]:0));
        comp.nydrift[yi][i] = cumAtemp[i] * P.energiNy * t.mixNy / 1000;
        const vkm = (hhUtb[i] * P.bilFaktorUtb + hhBef[i] * P.bilFaktorBef) * S.cph[i] * S.km[i];
        if (P.perspektiv === 'B') comp.nymob[yi][i] = vkm * (epv(i, t)*(1-shift)+shift*altPerVkm);
        sVkm += vkm; pop[yi][i] = S.bef[i] + cumInv[i]; nyaInv[yi][i] = cumInv[i]; nyBta[yi][i] = cumBta[i];
        sB += comp.bygg[yi][i]; sO += comp.omb[yi][i]; sM += mark[i]; sA += comp.anl[yi][i]; sU += utv[i];
      }
      if (P.perspektiv === 'A') { const g = P.andelKmInomMalmo * sVkm / S.cityAvkm; for (let i = 0; i < n; i++) comp.nymob[yi][i] = comp.mob[yi][i] * g; }
      popForra = popY;
      stad.push({year: y, pop: popY, N, invSuff, bost, brutto, suffBta: brutto - btaBost - nyLok, btaBost, nyFbh, nySm: behovSm, nyLok, omv, pab, riv, ren, ers,
        dwNy, dwUtb, dwFort, dwOmv, dwPab, fullt, takOmv: onskOmv - omv > 1e-9 && takOmv - cumOmv <= 1e-6, takPab: onskPab - pab > 1e-9 && takPab - cumPab <= 1e-6,
        fF: t.fF * tra * ab, fS: t.fS * ab, fL: t.fL * tra * ab, efEl: t.fk.el, efFv: t.fk.fv, flotta: t.fl, iAnl: t.iAnl, byggdel: comp.byggdel[yi].reduce((a,b)=>a+b,0), bygg: sB, anl: sA, omb: sO, mark: sM, utvHa: sU, nyVkm: sVkm});
    });

    return {P, years, comp, pop, nyaInv, nyBta, stad, Cu, risk, trafikHh, typologi: ty, tra, ab,
      areas: areas.map(a => ({id: a.id, namn: a.namn, kategori: a.kategori, fokus: a.fokus, bostader: a.bostader, arbetsplatser: a.arbetsplatser, ha: a.ha, Au: a.Au,
        Cu: a.Cu, tagen: a.tagen, L: a.L, dw: a.dw, arb: Math.min(a.arbetsplatser, a.arb), f: a.f, mark: a.mark, trafik: a.trafik, poang: a.poang})),
      tak: {omv: takOmv, pab: takPab, cumOmv, cumPab}};
  }

  /* Lokaliseringsindikatorn: klimatpåverkan som en ny bostad skulle orsaka om den byggdes i DeSO:n, t CO2e 2025–2050.
       trafik = Σ år bilar per hushåll × km per bil × t per fordonskilometer (värd-DeSO:ns värden)
       bygg   = BTA per bostad × klimatfaktor år 2030 (blandningen av flerbostadshus och småhus)
       mark   = markanspråk per bostad × ohårdgjord andel i DeSO:n × förlust per hektar (förväntad förlust om läget i DeSO:n är okänt) */
  function perBostad(S, R, i) {
    const P = R.P, aF = P.andelFbh / 100, t = R.stad.find(r => r.year === 2030);
    const trafik = R.trafikHh[i] * P.bilFaktorBef, bygg = (aF * housing(P).fbh * t.fF + (1 - aF) * housing(P).smahus * t.fS) / 1000;
    const andel = S.kolYta[i] > 0 ? Math.min(1, S.Au[i] / S.kolYta[i]) : 0, mark = R.typologi.ha * andel * R.risk[i];
    return {trafik, bygg, mark, total: trafik + bygg + mark};
  }

  /* Värden för valt år ('ack' = summa 2025–2050) som en rad per DeSO, med statiska indikatorer. */
  function view(S, R, ar) {
    const n = S.n, sel = ar === 'ack' ? R.years.map((y, i) => [y, i]).filter(([y]) => y >= ACK[0] && y <= ACK[1]).map(x => x[1]) : [R.years.indexOf(Number(ar))];
    if (sel.some(i => i < 0)) throw new Error('Okänt år: ' + ar);
    const sist = sel[sel.length - 1], rows = [];
    for (let i = 0; i < n; i++) {
      const r = {id: S.ids[i], i, namn: S.namn[i], land_ha: S.landHa[i]};
      let tot = 0;
      for (const c of KOMP) { let v = 0; for (const yi of sel) v += R.comp[c][yi][i]; r[c] = v; tot += v; }
      r.total = tot; r.mob_tot = r.mob + r.nymob; r.energi_tot = r.energi + r.nydrift; r.ny_tot = r.bygg + r.anl; r.bygg_tot = r.bygg + r.anl + r.omb + r.byggdel;
      r.bef = R.pop[sist][i]; r.nya_inv = R.nyaInv[sist][i]; r.bta_ny = R.nyBta[sist][i];
      // statiska indikatorer
      r.kol_forrad = (S.markkolC[i] + S.bioC[i]) * C_TO_CO2;                      // t CO2e bundet i mark och vegetation
      r.kol_ha = S.Au[i] > 0 ? (S.markkolC[i] + S.bioC[i]) / S.Au[i] : null;      // t C per ha ohårdgjord mark
      r.ohardgjord = S.kolYta[i] > 0 ? 100 * S.Au[i] / S.kolYta[i] : null;        // %
      r.kol_risk = S.Au[i] > 0 ? R.risk[i] : null;                                // t CO2e per ha som bebyggs
      r.bil_hh = R.P.lokalaData[r.id]?.bilarPerHushall ?? (S.hh[i] > 0 ? S.bil[i] / S.hh[i] : null);
      r.kwh_m2 = S.atemp[i] > 0 ? ((R.P.lokalaData[r.id]?.kwhEl ?? S.kwhEl[i]) + (R.P.lokalaData[r.id]?.kwhFv ?? S.kwhFv[i])) / S.atemp[i] : null;
      r.pot_omv = S.btaLokal[i]; r.pot_pab = S.btaFbh[i];
      const pb = perBostad(S, R, i); r.per_bostad = pb.total; r.pb = pb;
      rows.push(r);
    }
    const city = {land_ha: 0, bef: 0, nya_inv: 0, bta_ny: 0, kol_forrad: 0, pot_omv: 0, pot_pab: 0};
    for (const k of [...KOMP, 'total', 'mob_tot', 'energi_tot', 'ny_tot', 'bygg_tot']) city[k] = 0;
    for (const r of rows) for (const k of Object.keys(city)) city[k] += r[k] || 0;
    return {rows, city, years: sel.length, ar};
  }
  /* Skillnaden mot referensen (hela behovet nybyggs): undvikna utsläpp från byggande, anläggning och mark per DeSO, t CO2e. */
  function undvikt(v, vRef) {
    return v.rows.map((r, i) => vRef.rows[i].bygg_tot + vRef.rows[i].mark - r.bygg_tot - r.mark);
  }

  /* Stadens värden per år. */
  function stadPerAr(R) {
    return R.years.map((y, yi) => { const o = {year: y}; let tot = 0; for (const c of KOMP) { o[c] = R.comp[c][yi].reduce((a, b) => a + b, 0); tot += o[c]; }
      o.total = tot; o.bef = R.pop[yi].reduce((a, b) => a + b, 0); for (const p of PERSPEKTIV_ID) o['p_' + p] = PERSPEKTIV[p].komp.reduce((s, c) => s + o[c], 0); return o; });
  }
  /* Summor per byggperiod (fram till 2030, 2035, 2040, 2045 och 2050): folkökning, BTA-behov, hur behovet möts och klimatpåverkan. */
  function perioder(R) {
    const ar = stadPerAr(R), F = ['N', 'invSuff', 'bost', 'brutto', 'suffBta', 'btaBost', 'nyFbh', 'nySm', 'nyLok', 'omv', 'pab', 'riv', 'ren', 'ers', 'dwNy', 'dwUtb', 'dwFort', 'dwOmv', 'dwPab', 'fullt', 'utvHa'];
    return PERIOD.map(([a, b]) => {
      const o = {fran: a, till: b, ar: b - a + 1}; for (const f of F) o[f] = 0; for (const c of [...KOMP, 'total']) o[c] = 0;
      R.stad.forEach((s, i) => { if (s.year < a || s.year > b) return; for (const f of F) o[f] += s[f]; for (const c of [...KOMP, 'total']) o[c] += ar[i][c]; });
      o.pop = R.stad.find(s => s.year === b).pop;
      o.nybyggd = o.nyFbh + o.nySm + o.nyLok + o.ers;                 // m² BTA som nybyggs
      o.behov = o.brutto + o.riv;                                      // m² BTA som behövs utan cirkulära åtgärder
      o.byggande = o.bygg + o.anl + o.omb + o.byggdel;                             // t CO2e för att möta behovet
      return o;
    });
  }

  /* Omräkning till funktionell enhet. Statiska indikatorer har egen enhet och räknas inte om. */
  const STATISKA = {kol_forrad: 't CO₂e bundet', kol_ha: 't C per ha ohårdgjord mark', ohardgjord: '% ohårdgjord mark', kol_risk: 't CO₂e per ha som bebyggs',
    bil_hh: 'bilar per hushåll', kwh_m2: 'kWh per m² Atemp och år', pot_omv: 'm² BTA lokaler', pot_pab: 'm² BTA flerbostadshus', per_bostad: 't CO₂e per ny bostad, 2025–2050',
    nya_inv: 'nya invånare sedan 2024', bta_ny: 'm² BTA tillkommen sedan 2024'};
  function metric(row, key, unit) {
    const v = row[key];
    if (v == null) return null;
    if (key in STATISKA) return v;
    if (unit === 't') return v;
    if (unit === 't_ha') return row.land_ha > 0 ? v / row.land_ha : null;
    if (unit === 'kg_ha') return row.land_ha > 0 ? v * 1000 / row.land_ha : null;
    if (unit === 't_inv') return row.bef > 0 ? v / row.bef : null;
    throw new Error('Okänd enhet');
  }

  return {VERSION, BAS, SLUT, AR, MIL, PERIOD, ACK, KOMP, NAMN, KORT, PERSPEKTIV, PERSPEKTIV_ID, BYGG, P75_PROXY, TAKTPERIOD, UTV, EL_ALT, BECCS, POP_STD, POP_NIVA,
    DEFAULTS, LIMITS, ENUMS, CIRK, CIRK_NIVA, STATISKA, C_TO_CO2,
    housing, circularComparison, circularAttribution, LOCAL_FIELDS, validateLocal, params, utanCirk, harCirk, prepare, compute, view, undvikt, stadPerAr, perioder, metric, perBostad,
    indexAr, faktorer, flottaIndex, bilprodIndex, byggFaktor, folkmangd, kolPerHa, typologi, ramp};
});

files.app/r2z_op.css:
/* MalmoOP-tillägg ovanpå Vägvis grundstil. Samma palett, typografi och avstånd. */
:root{--c-energi:#1baf7a;--c-mobilitet:#2a78d6;--c-bygg:#eb6834;--c-mark:#6250d6;--c-nydrift:#eda100;--c-nymob:#e87ba4}
.brandmark{font-size:26px}
.year-switch{display:flex;gap:3px;background:#eef2eb;padding:4px;border-radius:9px;flex-wrap:wrap}
.year-switch button{padding:7px 11px;font-size:11.5px;background:none;color:#4f6560;font-variant-numeric:tabular-nums}
.year-switch button.active{background:#fff;box-shadow:0 1px 5px #0000000f;color:var(--teal)}
.year-switch button:hover:not(.active){color:var(--ink)}
.kpis.four{grid-template-columns:1.6fr 1fr 1fr 1fr}
.kpi-value .unit{font-size:12px;letter-spacing:0;font-weight:400}
.delta-up{color:#9c352e}.delta-down{color:#1d6a45}
.kpi-main .delta-up,.kpi-main .delta-down{color:#e9d6a6}
.parts .component-row{grid-template-columns:170px 1fr 92px}
.parts .fill{border-radius:0 4px 4px 0}
.parts .component-row i.sw{display:inline-block;width:10px;height:10px;border-radius:3px;margin-right:7px;vertical-align:-1px}
.parts .component-row .lbl{font-size:11.5px;color:var(--text)}
.parts .component-row.utanfor{opacity:.55}.parts .component-row.utanfor .lbl small{color:var(--muted,#6b7a74)}
.parts .component-row .lbl small{display:block;color:var(--muted);font-size:10px}
.parts .component-total{font-size:12.5px}
.chart-wrap{position:relative}
.chart-wrap svg{display:block;width:100%;height:auto;overflow:visible}
.chart-wrap .gridline{stroke:#e6ece6;stroke-width:1}
.chart-wrap .axis-label{fill:var(--muted);font-size:10px;font-variant-numeric:tabular-nums}
.chart-wrap .x-label{fill:var(--text);font-size:10.5px;font-variant-numeric:tabular-nums}
.chart-wrap .x-label.sel{fill:var(--ink);font-weight:700}
.chart-wrap .bar-hit{fill:transparent;cursor:pointer}
.chart-wrap .bar-hit:hover+g rect,.chart-wrap g.bar.hover rect{opacity:.85}
.chart-wrap g.bar.sel .sel-mark{fill:var(--ink)}
.chart-tip{position:absolute;pointer-events:none;background:#fff;border:1px solid var(--line);border-radius:9px;box-shadow:0 4px 18px #0b2e2826;padding:9px 11px;font-size:11.5px;min-width:210px;z-index:10;display:none}
.chart-tip b{display:block;color:var(--ink);font-size:12px;margin-bottom:5px}
.chart-tip div{display:flex;justify-content:space-between;gap:12px;margin:2px 0;font-variant-numeric:tabular-nums}
.chart-tip div span:first-child{display:flex;align-items:center;gap:6px}
.chart-tip i{width:9px;height:9px;border-radius:2px;display:inline-block}
.chart-tip .tip-total{border-top:1px solid var(--line);margin-top:5px;padding-top:5px;font-weight:700;color:var(--ink)}
.chart-legend{display:flex;flex-wrap:wrap;gap:6px 16px;margin-top:10px;font-size:11px;color:var(--text)}
.chart-legend span{display:flex;align-items:center;gap:6px}
.chart-legend i{width:10px;height:10px;border-radius:3px;display:inline-block}
.chart-legend b{font-variant-numeric:tabular-nums;color:var(--ink);font-weight:600}
.map-toolbar2{display:flex;flex-wrap:wrap;gap:10px 14px;align-items:center;margin-bottom:14px}
.map-toolbar2 label.inline{display:flex;align-items:center;gap:8px;font-size:12.5px;color:var(--ink)}
.map-toolbar2 select{min-width:220px}
.map-checks{display:flex;gap:16px;align-items:center;flex-wrap:wrap;margin-bottom:10px}
.map-checks label{font-size:12px;display:flex;align-items:center;gap:6px}
.map-checks input{accent-color:var(--teal)}
.map-checks .map-fit{margin-left:auto}
.map-legend i.dev1{border:2px solid #a76019;background:transparent;height:10px}
.map-legend i.dev2{border:2px dashed #a76019;background:transparent;height:10px}
.leaflet-tooltip.dev-tip{border-color:#e6cfa8}
#map-status{margin-top:8px}
.field-group h2{margin-bottom:4px}
.field-group .card-sub{margin-bottom:16px}
.controls .field input[type=number]{max-width:100%}
.field .src{display:block;font-size:10px;color:var(--muted);margin-top:5px;line-height:1.45}
.changed-dot{display:inline-block;width:7px;height:7px;border-radius:50%;background:#daa84d;margin-left:6px;vertical-align:1px}
.tbl-sort th{cursor:pointer;user-select:none}
.tbl-sort th.sorted:after{content:' ↓';color:var(--teal)}
.tbl-sort th.sorted.asc:after{content:' ↑'}
.area-table td.numeric small{display:block}
.chip{display:inline-block;border-radius:5px;padding:1px 7px;font-size:10px;font-weight:650;white-space:nowrap}
.chip.f1{background:#fcf1db;color:#7b4a13}.chip.f2{background:#eef2eb;color:#4f6560;border:1px dashed #b9c3be}
.chip.vo{background:#e4e8f3;color:#3d4f7c}.chip.bs{background:#dcefe4;color:#1d6a45}
.kv{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:6px 0}
.kv>div{border-top:1px solid var(--line);padding-top:9px}
.kv b{display:block;font-size:22px;font-weight:650;color:var(--ink);font-variant-numeric:tabular-nums;line-height:1.25}
.kv span{font-size:10.5px;color:var(--muted)}
.method-text ul{padding-left:18px}
.method-text code,.formula code{font-family:Consolas,Menlo,monospace;font-size:11.5px;background:#f0f4ee;padding:1px 5px;border-radius:4px}
.refs li{margin:9px 0;font-size:12px;line-height:1.6}
.refs a{word-break:break-word}
.ad-intervall{font-size:10.5px;color:var(--muted);display:block;margin-top:2px}
.quality-table td{white-space:normal}
.notice ul{margin:6px 0 0;padding-left:18px}
@media(max-width:1150px){.kpis.four{grid-template-columns:1fr 1fr}.kv{grid-template-columns:repeat(2,1fr)}.parts .component-row{grid-template-columns:130px 1fr 80px}}
@media(max-width:720px){.kpis.four{grid-template-columns:1fr}.year-switch button{padding:6px 8px;font-size:10.5px}.map-toolbar2 select{min-width:0;width:100%}.map-toolbar2 label.inline{flex-wrap:wrap;width:100%}}
@media print{.year-switch,.map-checks,.map-toolbar2{display:none!important}}
/* 1.1 Osäkerhet i energidelen */
.u-card .u-head{align-items:flex-start}
.u-run .progress{margin-top:4px}
.u-run p{margin:7px 0 0}
.u-stale{display:flex;flex-wrap:wrap;align-items:center;gap:10px 14px;background:#f3f7f2;border:1px solid #d8e6dc;border-radius:10px;padding:10px 14px}
.u-stale .primary span{padding-left:8px}
.u-done{margin:0 0 4px}
.u-grid{display:grid;grid-template-columns:minmax(230px,.9fr) 1.6fr;gap:26px;align-items:start;margin-top:14px}
.u-facts{margin:0}
.u-facts div{border-top:1px solid var(--line);padding:10px 0}
.u-facts dt{font-size:10px;letter-spacing:.7px;text-transform:uppercase;color:var(--muted);font-weight:650}
.u-facts dd{margin:3px 0 0;font-size:19px;font-weight:650;color:var(--ink);font-variant-numeric:tabular-nums}
.u-facts dd small{display:block;font-size:10.5px;font-weight:400;color:var(--muted);margin-top:2px}
.u-line{display:flex;align-items:center;gap:6px;margin:10px 0 0}
.u-line .sw{display:inline-block;width:10px;height:10px;border-radius:2px}
.u-param{border-top:1px solid var(--line);margin-top:18px;padding-top:4px}
.u-param h3{margin:10px 0 8px}
.ad-facts .ad-wide{grid-column:1/-1}
td.iv{color:var(--muted)}
@media(max-width:1150px){.u-grid{grid-template-columns:1fr}}
@media print{.u-stale,.u-run{display:none!important}}
.calc-result small{display:block;font-size:10.5px;color:var(--muted);margin-top:1px}

/* Road2Zero-OP: logotyp och ordmärke, samma som i Road2Zero-Plan och Road2Zero-CityScenario */
.r2z-brand{font-size:19px;letter-spacing:-.6px;line-height:1.05}
.r2z-brand small{margin-top:4px}
.r2z-logo{display:inline-block;width:44px;height:44px;flex:0 0 44px;border-radius:12px;box-shadow:0 0 0 1px #3f8c76;overflow:hidden}
.r2z-logo svg{width:44px;height:44px;display:block}
.r2z-tva{color:#EDCE93;font-weight:700}
.r2z-modell{font-style:normal;color:#7fc8a9;font-weight:600}
.r2z-steg{display:flex;gap:14px;margin:0 0 14px}
.r2z-steg .nr{flex:0 0 30px;height:30px;border-radius:50%;background:var(--pale);color:var(--teal);font-weight:750;display:flex;align-items:center;justify-content:center}
.r2z-ex{background:var(--bg);border-left:3px solid var(--teal);padding:7px 11px;border-radius:0 8px 8px 0;font-size:13px;margin-top:5px}

/* Road2Zero-OP: Resultat & klimatbudget (samma vy som Road2Zero-Plan) */
.r2zr-urval .r2zr-rad{display:flex;gap:28px;flex-wrap:wrap;align-items:flex-start}
.r2zr-etikett{font-size:11px;font-weight:600;color:var(--ink);margin-bottom:7px}
.r2zr-piller{display:flex;flex-wrap:wrap;gap:6px}
.r2zr-pill{background:#fff;border:1px solid var(--line);color:var(--ink);padding:7px 13px;font-size:12px;font-weight:500;border-radius:999px}
.r2zr-pill:hover{background:#eef4ef}
.r2zr-pill.on{background:var(--pale);border-color:#9cc5b2;color:var(--dark);font-weight:650}
.r2zr-pill i{display:inline-block;width:10px;height:10px;border-radius:3px;margin-right:7px;vertical-align:-1px}
.r2zr-val{margin-top:16px;gap:18px!important}
.r2zr-val label.field{min-width:180px;flex:1 1 180px}
.r2zr-kpis{display:grid;grid-template-columns:1.35fr repeat(4,1fr);gap:12px;margin:16px 0}
.r2zr-kpis .card{padding:16px 18px}
.r2zr-kpis .kpi-value{font-size:25px;margin:8px 0 4px}
.r2zr-flikar{display:inline-flex;flex-wrap:wrap;margin:4px 0 16px}
.r2zr-fig{padding:0;margin:0 0 16px;min-height:220px;overflow:hidden}
.r2zr-paris{border-left:4px solid var(--teal);margin-bottom:16px}
.r2zr-paris p{font-size:12.5px;max-width:980px}
.r2zs-kpis4{grid-template-columns:repeat(3,1fr) 1.2fr}
.r2zs-farg{display:inline-block;width:10px;height:10px;border-radius:2px;margin-right:8px;vertical-align:-1px}
.r2zs-tab td.r2zs-ute{white-space:normal;font-size:11.5px;line-height:1.4;color:var(--muted,#56635e);min-width:150px;max-width:240px}
.r2zs-kod{display:block;font-size:10px;font-weight:400;color:var(--muted,#56635e);margin-top:2px;white-space:normal;line-height:1.35}
.r2zs-jmf th.numeric{min-width:130px;max-width:170px}
.r2zs-jmf td.numeric{vertical-align:top;max-width:190px}
.r2zs-jmf td:first-child{white-space:normal;min-width:190px;max-width:280px}
.r2zs-jmf td.r2zs-not{min-width:200px;max-width:320px}
@media(max-width:1150px){.r2zr-kpis{grid-template-columns:repeat(2,1fr)}}
@media(max-width:720px){.r2zr-kpis{grid-template-columns:1fr}}
/* stadens klimatredovisning (stad.js) */
.r2zs-tab tr.r2zs-sub td{color:var(--muted,#56635e);font-size:12.5px}
.r2zs-tab tr.r2zs-sum td{font-weight:650;border-top:1px solid var(--line)}
.r2zs-tab td:first-child{min-width:220px}
.r2zs-tab tr.r2zs-grupp td{border-top:1px solid var(--line);background:#f6f8f6}
.r2zs-tab td.r2zs-why,.r2zs-tab td.r2zs-def{font-size:12px;line-height:1.45;color:#3d4a45;min-width:320px;max-width:560px;white-space:normal}
.r2zs-full{max-height:none!important}
.r2zs-tab th{white-space:normal;vertical-align:bottom;line-height:1.35}
.r2zs-forklaring th.numeric{min-width:78px;max-width:110px}
.r2zs-tab td.r2zs-not{white-space:normal;min-width:300px;font-size:12px;line-height:1.45}
.r2zs-tab tr.r2zs-datarad td{border-bottom:0;padding-bottom:4px}
.r2zs-tab tr.r2zs-whyrow td{white-space:normal;font-weight:400;color:#3d4a45;font-size:12px;line-height:1.55;padding-top:2px;padding-bottom:14px;max-width:1100px}
.r2zs-tab tr.r2zs-whyrow:hover{background:none}
.r2zs-nyckel{font-size:11px;font-weight:650;letter-spacing:.04em;color:#7d939d}

/* Visas nu: gemensam rad på Översikt, Resultat & klimatbudget och Karta & områden */
.ctx-bar{display:flex;flex-wrap:wrap;align-items:center;gap:6px 18px;background:#fff;border:1px solid var(--line);border-left:4px solid var(--dark);border-radius:10px;padding:10px 16px;margin:0 0 16px;font-size:13px}
.ctx-title{font-size:11px;letter-spacing:.08em;text-transform:uppercase;color:var(--dark);font-weight:700;margin-right:4px}
.ctx-item{display:inline-flex;flex-direction:column;line-height:1.25}
.ctx-item small{font-size:10.5px;color:var(--muted);letter-spacing:.03em;text-transform:uppercase}
.ctx-btn{margin-left:auto;padding:6px 12px;font-size:12px}
.map-what{margin:8px 0 10px;padding:9px 12px;background:var(--pale);border-radius:8px;font-size:13px;line-height:1.45}
.r2zr-pill.off{opacity:.55;text-decoration:line-through;cursor:not-allowed}
.r2zr-kpis.spegel{margin-top:12px}

